/* prog22_snake_camel_convert.c
 *
 * Re‑implementation of the original obfuscated binary.
 * Behaviour:
 *   prog22_snake_camel_convert to_snake <text>   → snake_case
 *   prog22_snake_camel_convert to_camel <text>   → camelCase
 *   prog22_snake_camel_convert (wrong argc)     → prints "USAGE"
 *   prog22_snake_camel_convert (bad mode)       → prints "INVALID_MODE"
 *
 * The result is printed with puts (i.e. a trailing newline).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUTBUF_SIZE 1024          /* same limit as the original binary */

static char outbuf[OUTBUF_SIZE];

/* --------------------------------------------------------------------- */
/* Convert a snake_case string to camelCase.  Underscores are removed and
   the character that follows an underscore is upper‑cased.                */
static void to_camel(const char *src)
{
    size_t out = 0;
    int capitalize = 0;               /* true when the next char must be upper */

    for (size_t i = 0; src[i] != '\0' && out + 1 < OUTBUF_SIZE; ++i) {
        char c = src[i];

        if (c == '_') {               /* remember that the next char is special */
            capitalize = 1;
            continue;                 /* underscore itself is not copied */
        }

        if (capitalize) {
            c = (char)toupper((unsigned char)c);
            capitalize = 0;
        }
        outbuf[out++] = c;
    }
    outbuf[out] = '\0';
}

/* --------------------------------------------------------------------- */
/* Convert a camelCase (or mixed‑case) string to snake_case.
   Upper‑case letters become lower‑case and are preceded by '_' unless they
   are the very first character.                                          */
static void to_snake(const char *src)
{
    size_t out = 0;
    int first = 1;                    /* true for the first character */

    for (size_t i = 0; src[i] != '\0' && out + 2 < OUTBUF_SIZE; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (isupper(c)) {
            if (!first) {
                outbuf[out++] = '_';
            }
            c = (unsigned char)tolower(c);
        }
        outbuf[out++] = (char)c;
        first = 0;
    }
    outbuf[out] = '\0';
}

/* --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
    } else {
        puts("INVALID_MODE");
        return 0;
    }

    puts(outbuf);
    return 0;
}
